from pathlib import Path
import openpyxl
from datetime import datetime

def normalize_cell(val):
    if val is None:
        return ""
    if isinstance(val, datetime):
        return val.strftime("%Y-%m-%d %H:%M")
    return str(val).strip()

def find_target_file(workspace_path):
    xlsx_files = list(Path(workspace_path).glob("*.xlsx"))
    if not xlsx_files:
        return None
    # Prefer the exact master filename, then sorted appeals/log matches
    for f in xlsx_files:
        if f.name == "appeals_log_master.xlsx":
            return f
    for f in sorted(xlsx_files, key=lambda p: p.name):
        if "appeal" in f.name.lower() or "log" in f.name.lower():
            return f
    return xlsx_files[0]

def find_case_row(ws, case_id):
    # Locate the row by Case ID in column A (position may vary with sorting)
    for r in range(1, ws.max_row + 1):
        val = ws.cell(row=r, column=1).value
        if val is not None and str(val).strip() == case_id:
            return r
    return None

def verify(workspace_path, external_services_path=None):
    target_file = find_target_file(workspace_path)
    if target_file is None:
        return {"pass": False, "score": 0.0, "feedback": "No .xlsx file found in workspace"}
    try:
        wb = openpyxl.load_workbook(target_file, data_only=True)
        ws = wb.active
    except Exception as e:
        return {"pass": False, "score": 0.0, "feedback": f"Could not open {target_file.name}: {e}"}

    def get_cell(row, col):
        return normalize_cell(ws.cell(row=row, column=col).value)

    row = find_case_row(ws, "CASE-2026-00441")
    if row is None:
        return {"pass": False, "score": 0.0, "feedback": f"No row with Case ID 'CASE-2026-00441' found in column A of {target_file.name}"}
    # Columns: I=9, J=10, K=11, N=14, O=15, P=16, Q=17
    i7 = get_cell(row, 9)
    j7 = get_cell(row, 10)
    k7 = get_cell(row, 11)
    n7 = get_cell(row, 14)
    o7 = get_cell(row, 15)
    p7 = get_cell(row, 16)
    q7 = get_cell(row, 17)

    failures = []
    # I: receipt datetime — accept either 2026-11-03 14:15 or 2026-11-04 14:15
    if not ("14:15" in i7 and ("2026-11-03" in i7 or "2026-11-04" in i7)):
        failures.append(f"I{row} expected '2026-11-03 14:15' or '2026-11-04 14:15', got '{i7}'")
    # J: date only
    if not ("2026-11-03" in j7 or "2026-11-04" in j7):
        failures.append(f"J{row} expected '2026-11-03' or '2026-11-04', got '{j7}'")
    # K: N
    if k7.upper() not in ("N", "NO", "FALSE", "0"):
        failures.append(f"K{row} expected 'N', got '{k7}'")
    # N: decision deadline
    if not ("2026-11-05" in n7 and "10:00" in n7):
        failures.append(f"N{row} expected '2026-11-05 10:00', got '{n7}'")
    # O: contains Ontario and Parity
    if not ("ontario" in o7.lower() and "parity" in o7.lower()):
        failures.append(f"O{row} expected to contain 'Ontario' and 'Parity', got '{o7}'")
    # P: Y
    if p7.upper() not in ("Y", "YES", "TRUE", "1"):
        failures.append(f"P{row} expected 'Y', got '{p7}'")
    # Q: N
    if q7.upper() not in ("N", "NO", "FALSE", "0"):
        failures.append(f"Q{row} expected 'N', got '{q7}'")

    if failures:
        return {"pass": False, "score": 0.0, "feedback": f"CASE-2026-00441 (row {row}) cell failures: " + "; ".join(failures)}
    return {"pass": True, "score": 1.0, "feedback": f"CASE-2026-00441 (row {row}) cells verified: I={i7}, J={j7}, K={k7}, N={n7}, O={o7}, P={p7}, Q={q7}"}

