            elif exp_val.upper() == "N" and actual.upper() not in ("N", "NO", "FALSE", "0"):
                failures.append(f"{label}: expected '{exp_val}', got '{actual}'")
        elif exp_val in ("2026-11-04", "2026-11-11", "2027-01-03"):
            if exp_val not in actual:
                failures.append(f"{label}: expected '{exp_val}', got '{actual}'")
        else:
            if exp_val.lower() not in actual.lower():
                failures.append(f"{label}: expected '{exp_val}', got '{actual}'")
    if failures:
        return {"pass": False, "score": 0.0, "feedback": f"CASE-2026-00443 (row {row}) cell failures: " + "; ".join(failures)}
    return {"pass": True, "score": 1.0, "feedback": f"CASE-2026-00443 (row {row}) all required cells verified correctly"}

from pathlib import Path
import openpyxl
from datetime import datetime

def normalize_cell(val):
    if val is None:
        return ""
    if isinstance(val, datetime):
        return val.strftime("%Y-%m-%d")
    return str(val).strip()

def find_target_file(workspace_path):
    xlsx_files = list(Path(workspace_path).glob("*.xlsx"))
    if not xlsx_files:
        return None
    # Prefer the exact master filename, then sorted appeals/log matches
    for f in xlsx_files:
        if f.name == "appeals_log_master.xlsx":
            return f
    for f in sorted(xlsx_files, key=lambda p: p.name):
        if "appeal" in f.name.lower() or "log" in f.name.lower():
            return f
    return xlsx_files[0]

def find_case_row(ws, case_id):
    # Locate the row by Case ID in column A (position may vary with sorting)
    for r in range(1, ws.max_row + 1):
        val = ws.cell(row=r, column=1).value
        if val is not None and str(val).strip() == case_id:
            return r
    return None

def verify(workspace_path, external_services_path=None):
    target_file = find_target_file(workspace_path)
    if target_file is None:
        return {"pass": False, "score": 0.0, "feedback": "No .xlsx file found in workspace"}
    try:
        wb = openpyxl.load_workbook(target_file, data_only=True)
        ws = wb.active
    except Exception as e:
        return {"pass": False, "score": 0.0, "feedback": f"Could not open {target_file.name}: {e}"}

    def get_cell(row, col):
        return normalize_cell(ws.cell(row=row, column=col).value)

    row = find_case_row(ws, "CASE-2026-00442")
    if row is None:
        return {"pass": False, "score": 0.0, "feedback": f"No row with Case ID 'CASE-2026-00442' found in column A of {target_file.name}"}
    # I=9, K=11, P=16, Q=17, W=23
    i8 = get_cell(row, 9)
    k8 = get_cell(row, 11)
    p8 = get_cell(row, 16)
    q8 = get_cell(row, 17)
    w8 = get_cell(row, 23)

    failures = []
    if "2026-11-10" not in i8:
        failures.append(f"I{row}: expected '2026-11-10', got '{i8}'")
    if k8.upper() not in ("N", "NO", "FALSE", "0"):
        failures.append(f"K{row}: expected 'N', got '{k8}'")
    if p8.upper() not in ("N", "NO", "FALSE", "0"):
        failures.append(f"P{row}: expected 'N', got '{p8}'")
    if q8.upper() not in ("N", "NO", "FALSE", "0"):
        failures.append(f"Q{row}: expected 'N', got '{q8}'")
    if "mills" not in w8.lower() and "j. mills" not in w8.lower():
        failures.append(f"W{row}: expected 'J. Mills', got '{w8}'")

    if failures:
        return {"pass": False, "score": 0.0, "feedback": f"CASE-2026-00442 (row {row}) cell failures: " + "; ".join(failures)}
    return {"pass": True, "score": 1.0, "feedback": f"CASE-2026-00442 (row {row}) cells verified: I={i8}, K={k8}, P={p8}, Q={q8}, W={w8}"}

from pathlib import Path
import json
import re

def verify(workspace_path, external_services_path=None):
    if external_services_path is None:
        return {"pass": False, "score": 0.0, "feedback": "external_services_path is None; cannot check slack_data.json"}
    slack_path = Path(external_services_path) / "slack_data.json"
    if not slack_path.exists():
        return {"pass": False, "score": 0.0, "feedback": "slack_data.json not found"}
    with open(slack_path, "r") as f:
        data = json.load(f)
    messages_by_channel = data.get("messages", {})

    # Find the escalation message in D001 referencing CASE-2026-00441
    target_text = None
    for msg in messages_by_channel.get("D001", []):
        if isinstance(msg, dict):
            text = msg.get("text", "")
            if "CASE-2026-00441" in text and "ESCALATION" in text.upper():
                target_text = text
                break
    # Fallback: any D001 message with the case ID
    if target_text is None:
        for msg in messages_by_channel.get("D001", []):
            if isinstance(msg, dict):
                text = msg.get("text", "")
                if "CASE-2026-00441" in text:
                    target_text = text
                    break

    if target_text is None:
        return {"pass": False, "score": 0.0, "feedback": "No DM in D001 (Darnell Whitfield) found referencing CASE-2026-00441"}

    lower = target_text.lower()
    upper = target_text.upper()

    # Check for Format B-2 structured fields
    checks = [
        ("ESCALATION" in upper, "missing 'ESCALATION' header (Format B-2)"),
        ("CASE-2026-00441" in target_text, "missing Case # CASE-2026-00441"),
        (
            bool(re.search(r'type[:\s]', lower)) and "concurrent" in lower,
            "missing 'Type:' field with 'Concurrent'",
        ),
        (
            bool(re.search(r'deadline[:\s]', lower)) and ("2026-11-05" in target_text or "november 5" in lower or "nov 5" in lower),
            "missing 'Deadline:' field with 2026-11-05 / November 5",
        ),
        (
            bool(re.search(r'trigger[:\s]', lower)),
            "missing 'Trigger:' field (must cite specific §9.2 trigger)",
        ),
        (
            bool(re.search(r'summary[:\s]', lower)),
            "missing 'Summary:' field",
        ),
        (
            bool(re.search(r'recommend', lower)),
            "missing 'My Recommendation:' / recommendation field",
        ),
        (
            bool(re.search(r'requested action[:\s]', lower)) or bool(re.search(r'action[:\s]', lower)),
            "missing 'Requested Action:' field",
        ),
    ]
    failures = [msg for passed, msg in checks if not passed]
    if failures:
        return {"pass": False, "score": 0.0, "feedback": f"D001 DM for CASE-2026-00441 found but missing B-2 template fields: {'; '.join(failures)}"}
    return {"pass": True, "score": 1.0, "feedback": "D001 DM found with Format B-2 escalation for CASE-2026-00441 (all required fields present per SOP §9.3 / Appendix B)"}
